import json
import re
try:
    cards = json.loads(str(vars.get('cards_json') or '[]'))
    event = str(vars.get('selection_event') or '')
    name = str(vars.get('selection_name') or '').strip().casefold()
    digits = str(vars.get('selection_digits') or '').strip()
    vars['selection_state'] = 'ask'
    if event == 'silence':
        vars['silences'] = int(vars.get('silences') or 0) + 1
        if int(vars.get('silences') or 0) >= 3:
            vars['selection_state'] = 'silent_end'
    elif event != 'repeat':
        vars['silences'] = 0
        matches = []
        if event != 'all' and (name or digits):
            for card in cards:
                name_ok = not name or name in card['productName'].casefold()
                digits_ok = not digits
                if len(digits) == 4:
                    digits_ok = digits == card['cardNumberLast4']
                elif len(digits) == 6:
                    tail = card['cardNumber'][-6:]
                    digits_ok = bool(re.fullmatch('[0-9]{6}', tail)) and tail == digits
                elif len(digits) > 6 and vars.get('selection_state_previous') == 'full_required':
                    digits_ok = bool(re.fullmatch('[0-9]+', card['cardNumber'])) and digits == card['cardNumber']
                if name_ok and digits_ok:
                    matches.append(card)
        if len(matches) == 1:
            card = matches[0]
            vars['selected_card'] = card['cardNumber']
            vars['selected_intro'] = 'Sonu ' + ' '.join(card['cardNumberLast4']) + ' ile biten ' + card['productName'] + ' kartınız'
            vars['selection_state'] = 'selected'
            vars['selection_attempts'] = 0
        else:
            if len(matches) > 1:
                vars['card_options'] = json.dumps([{'ad': c['productName'], 'son_dort': ' '.join(c['cardNumberLast4'])} for c in matches], ensure_ascii=False)
                vars['selection_state'] = 'last_four_required'
                tails = [c['cardNumberLast4'] for c in matches]
                if len(set(tails)) == 1:
                    vars['selection_state'] = 'last_six_required'
                    sixes = [c['cardNumber'][-6:] for c in matches]
                    if all(re.fullmatch('[0-9]{6}', s) for s in sixes) and len(set(sixes)) == 1:
                        vars['selection_state'] = 'full_required'
            vars['selection_attempts'] = int(vars.get('selection_attempts') or 0) + 1
            if int(vars.get('selection_attempts') or 0) >= 3:
                vars['selection_state'] = 'exhausted'
    vars['selection_state_previous'] = vars.get('selection_state')
    vars['selection_event'] = ''
    vars['selection_name'] = ''
    vars['selection_digits'] = ''
except Exception:
    vars['selection_state'] = 'error'

