import json
import datetime
import re
try:
    vars['reading_state'] = 'error'
    if vars.get('balance_state') != 'ok':
        raise ValueError('Balance unavailable')
    data = json.loads(str(vars.get('balance_json') or '{}'))
    today = datetime.datetime.fromisoformat(str(vars.get('now'))).date()
    months = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
    dates = {}
    parsed = {}
    for key in ['statementDate','lastPayDate','nextStatementDate','nextLastPayDate']:
        raw = data.get(key, '')
        if raw:
            date = datetime.datetime.strptime(raw, '%d.%m.%Y').date()
            parsed[key] = date
            dates[key] = str(date.day) + ' ' + months[date.month-1] + ' ' + str(date.year)
    closing = parsed.get('statementDate') == today or parsed.get('nextStatementDate') == today
    overdue = 'lastPayDate' in parsed and parsed['lastPayDate'] < today
    issued = 'statementDate' in parsed and parsed['statementDate'] <= today
    no_debt = data.get('statementPaymentStatus') == 'NO_DEBT'
    vars['issued_date'] = data.get('statementDate', '') if issued else ''
    vars['no_statement_debt'] = 'yes' if no_debt or not issued else 'no'
    amounts = {}
    for key, currency, fraction in [('debtTL','Türk Lirası','kuruş'),('debtUSD','Dolar','sent'),('debtEUR','Euro','sent'),('debtGBP','İngiliz Sterlini','peni')]:
        block = data.get(key)
        if isinstance(block, dict) and block:
            amounts[key] = {}
            for field, value in block.items():
                raw = str(value)
                if not re.fullmatch('-?[0-9]+(?:\.[0-9]{1,2})?', raw):
                    raise ValueError('Unsupported exact monetary precision')
                parts = raw.split('.')
                whole = parts[0]
                decimal = (parts[1] if len(parts) > 1 else '').ljust(2, '0')
                text = whole + ' ' + currency
                if int(decimal) != 0:
                    text += ' ' + str(int(decimal)) + ' ' + fraction
                amounts[key][field] = text
    lines = [str(vars.get('selected_intro') or '') + '.']
    if closing:
        lines.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
    elif not issued:
        lines.append('Kartınızın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.')
        if 'nextStatementDate' in dates:
            lines.append('İlk hesap kesim tarihiniz ' + dates['nextStatementDate'] + ' olacak.')
    elif no_debt:
        lines.append(dates['statementDate'] + ' tarihli ekstrenizden borcunuz bulunmamaktadır.')
    elif overdue:
        lines.append('Son ödeme tarihiniz geçmiştir.')
    else:
        lines.append(dates['statementDate'] + ' tarihinde kesilen ekstrenize ait bilgiler:')
    clear = []
    currencies = []
    for key, currency, wire in [('debtTL','Türk Lirası','TL'),('debtUSD','Dolar','USD'),('debtEUR','Euro','EUR'),('debtGBP','İngiliz Sterlini','GBP')]:
        if key in amounts:
            currencies.append(wire)
        block = data.get(key)
        if key != 'debtTL' and isinstance(block, dict) and block.get('transferAmount', 0) > 0:
            lines.append(currency + ' borcunuzdan Türk Lirası borcunuza aktarım bulunmaktadır.')
    if (no_debt or not issued) and not closing:
        block = data.get('debtTL')
        if isinstance(block, dict) and 'totalDebt' in block:
            if block['totalDebt'] > 0:
                lines.append('Gelecek dönemler dahil toplam borcunuz ' + amounts['debtTL']['totalDebt'] + '.')
            else:
                lines.append('Gelecek dönemler dahil Türk Lirası borcunuz bulunmamaktadır.')
    else:
        for key, currency in [('debtTL','Türk Lirası'),('debtUSD','Dolar'),('debtEUR','Euro'),('debtGBP','İngiliz Sterlini')]:
            block = data.get(key)
            if not isinstance(block, dict) or not block:
                continue
            field = 'totalDebt' if closing or overdue else 'remainingDebt'
            if field not in block:
                raise ValueError('Missing debt')
            if block[field] <= 0:
                clear.append(currency)
                continue
            spoken = amounts[key]
            if closing or overdue:
                lines.append(currency + ' toplam borcunuz ' + spoken['totalDebt'] + '.')
            elif key != 'debtTL':
                lines.append(currency + ' ekstre borcunuz ' + spoken['statementDebt'] + ', kalan toplam borcunuz ' + spoken['remainingDebt'] + ', ödenmesi gereken minimum tutar ' + spoken['minPayment'] + '.')
            elif block['remainingMinPayment'] <= 0:
                lines.append('Türk Lirası ekstre borcunuz ' + spoken['statementDebt'] + ', kalan toplam borcunuz ' + spoken['remainingDebt'] + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            elif block['remainingMinPayment'] >= block['minPayment']:
                lines.append('Türk Lirası ekstre borcunuz ' + spoken['statementDebt'] + ', ödenmesi gereken minimum tutar ' + spoken['minPayment'] + '.')
            else:
                lines.append('Türk Lirası ekstre borcunuz ' + spoken['statementDebt'] + ', ödenmesi gereken minimum tutar ' + spoken['minPayment'] + ', kalan toplam borcunuz ' + spoken['remainingDebt'] + ', kalan minimum ödeme tutarınız ' + spoken['remainingMinPayment'] + '.')
        if clear:
            lines.append(' ve '.join(clear) + ' borcunuz bulunmamaktadır.')
    tl = data.get('debtTL', {})
    if overdue and data.get('automaticPaymentFlag') == 'Y' and isinstance(tl, dict) and tl.get('remainAutomaticPaymentAmount', 0) > 0:
        lines.append('Kalan otomatik ödeme tutarınız ' + amounts['debtTL']['remainAutomaticPaymentAmount'] + '.')
    due_key = 'nextLastPayDate' if closing and parsed.get('nextStatementDate') == today else 'lastPayDate'
    due_text = ''
    if due_key in dates:
        if parsed[due_key] == today:
            due_text = 'Borçlarınız için son ödeme tarihiniz bugündür.'
        elif parsed[due_key] < today:
            due_text = 'Son ödeme tarihiniz ' + dates[due_key] + ' idi; bu tarih geçmiştir.'
        else:
            due_text = 'Son ödeme tarihiniz ' + dates[due_key] + '.'
        lines.append(due_text)
    vars['due_only'] = due_text
    vars['minimum_only'] = 'Minimum ödeme tutarınız ' + amounts['debtTL']['minPayment'] + '.' if 'debtTL' in amounts and 'minPayment' in amounts['debtTL'] else ''
    vars['reading_text'] = ' '.join(lines)
    vars['available_currencies'] = ','.join(currencies)
    cards = json.loads(str(vars.get('cards_json') or '[]'))
    read = json.loads(str(vars.get('read_cards_json') or '[]'))
    selected = str(vars.get('selected_card') or '')
    if selected not in read:
        read.append(selected)
    vars['read_cards_json'] = json.dumps(read)
    vars['another_card'] = 'yes' if any(card['cardNumber'] not in read for card in cards) else 'no'
    vars['reading_state'] = 'ok'
except Exception:
    vars['reading_state'] = 'error'
    vars['reading_text'] = ''
